INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(73192, 'esMX', '', '', 19865),
(73210, 'esMX', '', '', 19865),
(73215, 'esMX', '¿Qué es esto que invade mi nueva guarida? ¿Una mascota de los Lobo Gélido, quizás?', '', 19865),
(73216, 'esMX', 'Espera, esto no es un Lobo Gélido.', '', 19865),
(73217, 'esMX', '¡Mátalo de todos modos! Veamos a qué sabe.', '', 19865),
(73631, 'esMX', '', '', 19865),
(73632, 'esMX', '', '', 19865),
(73633, 'esMX', '', '', 19865),
(73634, 'esMX', '', '', 19865),
(73635, 'esMX', '', '', 19865),
(73636, 'esMX', '', '', 19865),
(73637, 'esMX', '', '', 19865),
(73638, 'esMX', '', '', 19865),
(73849, 'esMX', '', '', 19865),
(73850, 'esMX', '', '', 19865),
(73851, 'esMX', '', '', 19865),
(73852, 'esMX', '', '', 19865),
(73853, 'esMX', '', '', 19865),
(73854, 'esMX', '', '', 19865),
(73855, 'esMX', '', '', 19865),
(73856, 'esMX', '', '', 19865),
(73857, 'esMX', '', '', 19865),
(73858, 'esMX', '', '', 19865),
(73859, 'esMX', '', '', 19865),
(73860, 'esMX', '', '', 19865),
(73861, 'esMX', '', '', 19865),
(73862, 'esMX', '', '', 19865),
(73863, 'esMX', '', '', 19865),
(73864, 'esMX', '', '', 19865),
(73865, 'esMX', '', '', 19865),
(73866, 'esMX', '', '', 19865),
(73867, 'esMX', '', '', 19865),
(73868, 'esMX', '', '', 19865),
(73869, 'esMX', '', '', 19865),
(73870, 'esMX', '', '', 19865),
(73872, 'esMX', '', '', 19865),
(73876, 'esMX', '', '', 19865),
(74239, 'esMX', 'Una extraña criatura. ¿Qué valiosas cosas encontraré en tu cadáver?', '', 19865),
(74246, 'esMX', 'Tonta criatura. Prueba el verdadero aguijón del desierto.', '', 19865),
(74247, 'esMX', '¡Vas a morir como la otra basura Lobo Gélido!', '', 19865),
(74248, 'esMX', 'Pensaste que había muerto, ¿no?', '', 19865),
(74249, 'esMX', 'Desafío a la muerte y a ti!', '', 19865),
(74250, 'esMX', 'Sus espadas no son rival para nuestra astucia.', '', 19865),
(74251, 'esMX', 'Puedes no ser un Lobo Gélido, pero SANGRARÁS como ellos.', '', 19865),
(74261, 'esMX', '¡Hatock, hijo del Lobo de Hierro! Vengo por tu cabeza.', '', 19865),
(74262, 'esMX', 'Lobo Gélido, maten al gronn. ¡Encuentren al cobarde!', '', 19865),
(74263, 'esMX', '¡ME VENGARÉ!', '', 19865),
(74272, 'esMX', '', '', 19865),
(74273, 'esMX', '', '', 19865),
(74274, 'esMX', '', '', 19865),
(74275, 'esMX', '', '', 19865),
(74276, 'esMX', '', '', 19865),
(74277, 'esMX', '', '', 19865),
(74278, 'esMX', '', '', 19865),
(74279, 'esMX', '', '', 19865),
(74280, 'esMX', '', '', 19865),
(74281, 'esMX', '¿Escuchas los vientos aullantes? Es un sonido solitario. No te confundas: si no tienes cuidado, la tierra te reclamará para sí.', '', 19865),
(74288, 'esMX', 'La impaciencia de Ga''nar puede destruir a los Lobo Gélido. Es típico en él poner sus necesidades por encima de las del clan.', '', 19865),
(74289, 'esMX', '', '', 19865),
(74290, 'esMX', 'No te preocupes. Mi valiente convencerá a Ga''nar de volver. Tu hermano valora la fuerza, y mi camarada la posee en abundancia.', '', 19865),
(74291, 'esMX', 'Temo que el costo de la impaciencia de Ga''nar será sangre Lobo Gélido', '', 19865),
(74292, 'esMX', 'Pero claro, Ga''nar siempre ha puesto sus propias necesidades antes que el clan.', '', 19865),
(74293, 'esMX', '¡Los huesos del uñagrieta anciano se agitan a la vida!', '', 19865),
(74295, 'esMX', '¡Noooo! ¡Necio! El ritual se... sale de control...', '', 19865),
(74296, 'esMX', '¿Quién se atreve a interrumpir mi magia?', '', 19865),
(74299, 'esMX', '¿Qué quieres?', '', 19865),
(74313, 'esMX', 'Un cachorro de lobo gélido mordisquea excitado tus tobillos antes de caminar a tu ritmo.', '', 19865),
(74316, 'esMX', '¡Ga''nar! Ya era hora de que regresaras. ¿Qué macabros trofeos son estos?', '', 19865),
(74317, 'esMX', 'Maté a los hijos del Lobo de Hierro. Hoy se ahogará en la sangre de su sangre.', '', 19865),
(74318, 'esMX', 'Tu cruzada de tontos nos dejó indefensos. Causaste la muerte de muchos.  ', '', 19865),
(74319, 'esMX', 'Tú no mereces llamarte jefe, hermano. Por mis derechos como el segundo de nuestro linaje, por la justicia que hoy he impuesto, declaro mak''gora.', '', 19865),
(74320, 'esMX', 'Así que a esto hemos llegado.', '', 19865),
(74321, 'esMX', 'EVENTO GENIAL EN EL JUEGO', 'EVENTO GENIAL EN EL JUEGO', 19865),
(74322, 'esMX', '', '¡No! ¡No deben hacer esto! ¡Comparten la misma sangre!', 19865),
(74323, 'esMX', 'La familia cuida de los suyos. ¡Solo yo busqué vengar a nuestro padre!', '', 19865),
(74324, 'esMX', 'La venganza no fortalece ni protege al clan. Es por esa actitud por la que él me eligió como su sucesor.', '', 19865),
(74325, 'esMX', 'Nuestro padre escogió mal. Este clan necesita FUERZA.', '', 19865),
(74326, 'esMX', 'Hazlo.', '', 19865),
(74327, 'esMX', 'Jefe.', '', 19865),
(74328, 'esMX', '', '', 19865),
(74329, 'esMX', '', '', 19865),
(74330, 'esMX', 'La venganza no nos hace fuertes, hermano. ', '', 19865),
(74331, 'esMX', 'Arriba, hermano. Te necesito. El clan te necesita.', '', 19865),
(74332, 'esMX', '', '', 19865),
(74333, 'esMX', '', '', 19865),
(74334, 'esMX', '', '', 19865),
(74335, 'esMX', '', '', 19865),
(74336, 'esMX', '¡Suficiente! Me rindo.', '', 19865),
(74337, 'esMX', 'Supongo que no eres un pelele.', '', 19865),
(74338, 'esMX', '¡Lok''tar!', '', 19865),
(74339, 'esMX', '¡No perteneces aquí! ¡Urtok te va a enseñar una lección sobre fuerza!', '', 19865),
(74340, 'esMX', '', '', 19865),
(74341, 'esMX', '', '', 19865),
(74342, 'esMX', '¿Aún vivo, cachorro? Supongo que no tendré que salvarte después de todo. Ven, debemos hablar.', '', 19865),
(74343, 'esMX', 'Oh, y trata de no morir. Los scorpar no son amables con los cadáveres.', '', 19865),
(74344, 'esMX', 'Tu cadáver me será muy útil. Pelo, carne y hueso. Puedo hacer muchos brebajes.', '', 19865),
(74345, 'esMX', '¿Por qué has venidos? ¿Fue por tus preciosos lobeznos? ¡Su carne es mía!', '', 19865),
(74346, 'esMX', '', '', 19865),
(74347, 'esMX', 'Tanto... poder...', '', 19865),
(74353, 'esMX', 'La carcasa se ve fresca y sin tallar, con la excepción de seis cuidadosas incisiones en la panza.$B$BDetrás de cada incisión encuentras una gran cavidad donde antes pudo estar algún órgano crítico.', '', 19865),
(74361, 'esMX', '¡Espera!', '', 19865),
(74362, 'esMX', '¿Ga''nar? ¿Eres tú? Pensé que ya te habíamos matado.', '', 19865),
(74363, 'esMX', '¿O te gustó tanto la primera vez que decidiste volver por más?', '', 19865),
(74364, 'esMX', '', '', 19865),
(74365, 'esMX', 'Si ruegas como un buen perro, tal vez mi padre...', '', 19865),
(74366, 'esMX', 'Tu padre QUIZÁS pueda identificar lo que queda de tu pequeño cráneo.', '', 19865),
(74367, 'esMX', 'Hrgh... M-... ¡¡MÁTENLOS!!', '', 19865),
(74368, 'esMX', '', '', 19865),
(74369, 'esMX', '', '', 19865),
(74370, 'esMX', '', '', 19865),
(74371, 'esMX', '¡Montemos!', '', 19865),
(74377, 'esMX', '', '', 19865),
(74378, 'esMX', '', '', 19865),
(74379, 'esMX', '', '', 19865),
(74380, 'esMX', 'Este guerrero murió de varias marcas de perforación en su cuerpo. Fue posicionado en forma cuidadosa y ceremonial antes de ser quemado.', '', 19865),
(74381, 'esMX', 'Por favor... MÁTAME...', '', 19865),
(74382, 'esMX', 'La magia... arde... ¡AAAGGGHHHHH!', '', 19865),
(74392, 'esMX', '¿Durok? ¿Qué brujería vil es esta?', '', 19865),
(74393, 'esMX', 'Mi hermano se ha ido, y solo queda esta criatura. ¡Debe ser destruida!', '', 19865),
(74394, 'esMX', 'Destruiré este sucio altar mientras te haces cargo de Kurak''akan.', '', 19865),
(74395, 'esMX', '', '', 19865),
(74396, 'esMX', '¡Escuchen, Señor del Trueno! ¡Soy Ga''nar de los Lobo Gélido! ¡Hijo de Garad!', '', 19865),
(74397, 'esMX', 'Tu jefe asesinó a mi padre. Así que vengo a reclamar las cabezas de sus hijos. ¿Quién de ustedes tiene el valor para detenerme?', '', 19865),
(74398, 'esMX', 'Prepárense...', '', 19865),
(74399, 'esMX', '', '', 19865),
(74400, 'esMX', '', '', 19865),
(74401, 'esMX', '', '', 19865),
(74402, 'esMX', '', '', 19865),
(74403, 'esMX', '', '', 19865),
(74407, 'esMX', 'Vamos $r, cabalgo al campamento de exiliados inmediatamente.', '', 19865),
(74408, 'esMX', '', '', 19865),
(74409, 'esMX', 'Sabíamos que los scorpar eran una vil plaga, pero nunca supimos cómo pudieron crecer en número.', '', 19865),
(74410, 'esMX', 'No importa. Kurak''akan está muerto, gracias a ti. La amenaza del scorpra Kuraki está en ruinas.', '', 19865),
(74411, 'esMX', '', '', 19865),
(74412, 'esMX', 'Hermanos, miren. $gUn forastero:Una forastera;.', '', 19865),
(74413, 'esMX', '¡Vragor! ¿Quién es el enano?', '', 19865),
(74414, 'esMX', 'No es un chucho, Jefe. Respondo por $geste forastero:esta forastera;.', '', 19865),
(74415, 'esMX', '', '', 19865),
(74416, 'esMX', '¡Adelante, hermanos y hermanas! ¡Atraviesen el campamento y reúnanase al Risco Salvaje!', '', 19865),
(74417, 'esMX', '¡Lok''tar ogar!', '', 19865),
(74418, 'esMX', '¡Lok''tar ogar!', '', 19865),
(74419, 'esMX', '¡Lok''tar ogar!', '', 19865),
(74420, 'esMX', 'Apuesto a que puedo matar más gronns que tú, hermano.', '', 19865),
(74421, 'esMX', '¡Coman, muchachos! Tenemos gronns que matar.', '', 19865),
(74422, 'esMX', 'Afilen las hojas, afilen las hojas...', '', 19865),
(74423, 'esMX', 'Buena punta. Perfecta para apuñalar un gronn en el ojo o a un Señor del Trueno en el pecho.', '', 19865),
(74424, 'esMX', '¡Deténgan$Glo:la;!', '', 19865),
(74425, 'esMX', '¡No dejen que pase!', '', 19865),
(74426, 'esMX', '¡No dejen que escape!', '', 19865),
(74435, 'esMX', '<Ga''nar está reuniendo su fuerza para desafiar al enorme gronn.>', '', 19865),
(74436, 'esMX', '<Ayuda a Ga''nar en la batalla.>', '<Ayuda a Ga''nar en la batalla.>', 19865),
(74442, 'esMX', '', '', 19865),
(74443, 'esMX', '', '', 19865),
(74446, 'esMX', '', '', 19865),
(74447, 'esMX', '', '', 19865),
(74451, 'esMX', 'Mi muerte no significa nada. ¡No puedes detener la tormenta!', '', 19865),
(74452, 'esMX', 'No puedes detenernos... ¡en tanto que Kurak''akan viva!', '', 19865),
(74453, 'esMX', '¡Tonto, no has conseguido nada! Nuestro verdadero poder está en el valle al norte.', '', 19865),
(74454, 'esMX', '', '', 19865),
(74455, 'esMX', '', '', 19865),
(74456, 'esMX', '', '', 19865),
(74457, 'esMX', 'Dile a Vragor por qué te envió Durotan.', 'Dile a Vragor por qué te envió Durotan.', 19865),
(74460, 'esMX', '', '', 19865),
(74461, 'esMX', '', '', 19865),
(74462, 'esMX', 'Quédense aquí hasta que lleguen refuerzos. Mientras tanto, atraigamos a tantos como podamos…', '', 19865),
(74463, 'esMX', '¡Wraaugh!', '', 19865),
(74490, 'esMX', 'Mientras tanto, atraigamos tantos como podamos...', '', 19865),
(74491, 'esMX', 'Luchaste bien contra Urtok. Veamos si estos trucos funcionan contra un gronn.', '', 19865),
(74492, 'esMX', '¿Te envió Durotan? Debió venir él mismo. Después de todo, estamos vengando a SU padre.', '', 19865),
(74493, 'esMX', 'Recuerdo la primera vez que tuve que alimentar a los lobos. Casi perdí la mano en el proceso.', '', 19865),
(74494, 'esMX', 'Los exploradores encontraron a Kolloc en el otro lado del Oasis Aguja del Filo. Prepárate para salir pronto.', '', 19865),
(74495, 'esMX', 'Dicen que los Señores del Trueno están entre nosotros y los gronn. Deben ser un buen calentamiento. ¡Ja!', '', 19865),
(74496, 'esMX', 'Un $c ¿hmm? ¿Cómo eres en una pelea de verdad?', '', 19865),
(74497, 'esMX', '', '', 19865),
(74498, 'esMX', 'Se necesitará más que una pizca de carne para ganar el corazón de un verdadero Lobo Gélido. Aunque no afecta.', '', 19865),
(74502, 'esMX', '', '', 19865),
(74503, 'esMX', '', '', 19865),
(74511, 'esMX', '', '', 19865),
(74689, 'esMX', '', '¡Drek''Thar! No sé qué estás haciendo ahí arriba, pero estás sacando de quicio a los goren.', 19865),
(74690, 'esMX', 'Copiando', 'Copiando', 19865),
(74735, 'esMX', '¿Karg? Sí, lo vi. Salvó mi vida. Mató él mismo a cinco de esos sucios Señores del Trueno.', '¿Karg? Sí, lo vi. Salvó mi vida. Mató él mismo a cinco de esos sucios Señores del Trueno.', 19865),
(74736, 'esMX', 'Él los tenía, también. Hasta que apareció el Lobo de Hierro montando el rylak más grande y malo que he visto jamás. Lo atrapó y se lo llevó.', 'Él los tenía, también. Hasta que apareció el Lobo de Hierro montando el rylak más grande y malo que he visto jamás. Lo atrapó y se lo llevó.', 19865),
(74737, 'esMX', 'Se llevaron a otros, también. Arrastrados hacia el cañón. Pregunta por ahí, averigua quién ha desaparecido.', 'Se llevaron a otros, también. Arrastrados hacia el cañón. Pregunta por ahí, averigua quién ha desaparecido.', 19865),
(74738, 'esMX', '', '', 19865),
(74739, 'esMX', '', '', 19865),
(74740, 'esMX', '', '', 19865),
(74741, 'esMX', 'Vine a pedirle a los elementos su ayuda en la próxima batalla.', '', 19865),
(74742, 'esMX', 'Pero entre los ardientes y penetrantes vientos de las montañas, escucho el grito de la Furia, Exurotus.', '', 19865),
(74743, 'esMX', 'Vencida, medio consumida y destrozada por magia antigua, la Furia es la prisionera del magnaron Kron.', '', 19865),
(74744, 'esMX', 'La Furia ha sido fragmentada, sus pedazos dispersos en el viento o consumidos por carroñeros.', '', 19865),
(74745, 'esMX', '¡Mi mozo de cuadra, Roknor, trató de combatir contra uno de esos rylaks con una horqueta y fue arrastrado dentro de la Escoria de Huesos!', '', 19865),
(74746, 'esMX', '', 'No he visto a Makar en algún tiempo. ¡Necesitamos desesperadamente sus habilidades de sanación!', 19865),
(74747, 'esMX', '', '¡Una de estas cosas se llevó a mi hija Gana! ¡La arrastró en cadenas como a un animal!', 19865),
(74750, 'esMX', '', 'Qué inusual que Akama envíe a $gun extraño:una extraña;...', 19865),
(74751, 'esMX', '', '...pero confío en ti. Gracias, $gforastero:forastera;.', 19865),
(74752, 'esMX', 'Ajá. Ya era tiempo de que nos vengáramos de estos sucios orcos.', '', 19865),
(74753, 'esMX', '¿QUÉ? ¿OH? ¿IR A AKAMA? ¡¡¡BIEN!!!', '', 19865),
(74756, 'esMX', '', '', 19865),
(74758, 'esMX', 'Los tenemos dominados. ¡Ahora es tiempo de hacerlos retroceder!', '', 19865),
(74759, 'esMX', '', 'Te seguiré adonde vayas, Akama.', 19865),
(74760, 'esMX', '¡Debemos echar a esas ratas orcas de nuestro templo! Sentirán todo el peso de la justicia draenei.', '', 19865),
(74761, 'esMX', '¡ME GUSTA SANARME A MÍ MISMO!', '', 19865),
(74762, 'esMX', 'Por la Luz... necesitaremos que alguien se encargue de esa artillería orca.', '', 19865),
(74763, 'esMX', '¡ESTOY EN ELLO!', '', 19865),
(74764, 'esMX', 'Eso veo.', '', 19865),
(74765, 'esMX', '¡Ahura! ¡Hogo! ¡$n! ¡Sigan con la ofensiva!', '', 19865),
(74766, 'esMX', '', 'Comandante, no puedo dejar estos hombres aquí. Ustedes tres continúen sin mí.', 19865),
(74767, 'esMX', 'Muy bien. Mantente con vida, Ahura.', '', 19865),
(74768, 'esMX', 'Hogo, $n. Estos orcos no van a matarse solos.', '', 19865),
(74769, 'esMX', 'Hogo, sigue adelante. Asegúrate de que no contraataquen. Me quedaré atrás y prepararé defensas.', '', 19865),
(74770, 'esMX', 'Como desees, comandante.', '', 19865),
(74771, 'esMX', '¡$n¡ ¡Síganme hacia las fauces del enemigo! ¡¡POR LA LUZ DE KARABOR!!', '', 19865),
(74773, 'esMX', '', 'Drek''Thar puede dudar de sus capacidades, pero yo no.$b$bNo voy a dejar a ese tonto ciego darle la espalda a los elementos. No después de todo lo que han hecho por nuestro pueblo.', 19865),
(74774, 'esMX', 'Por aquí.', 'Por aquí.', 19865),
(74783, 'esMX', '', '¡Espera, $p! Por aquí. Antes de que el gigante te vea.', 19865),
(74784, 'esMX', '¡Akama! ¿Por qué no arrasar su pueblo? ¿Por qué darles otra oportunidad?', '', 19865),
(74785, 'esMX', 'La palabra de un orco es basura. Solo están comprando tiempo.', '', 19865),
(74786, 'esMX', 'Basta de hablar de batallas, Hogo. Por fin, Sombraluna disfruta de paz.', '', 19865),
(74787, 'esMX', 'O no.', '', 19865),
(74788, 'esMX', '¡ME DUELEN LOS OÍDOS!', '', 19865),
(74789, 'esMX', '', '¡Asha! Vamos, chica. ¡Karg y Nerok están en problemas!', 19865),
(74790, 'esMX', '', '', 19865),
(74818, 'esMX', '¿Qué es ese horrible olor?', 'Voy a vomitar...', 19865),
(74819, 'esMX', '¡¡¡aún enfermo!!!', '¡¡¡aún enfermo!!!', 19865),
(74820, 'esMX', '¡No los dejen pasar!', '', 19865),
(74821, 'esMX', '¡¡Protejan el templo!!', '', 19865),
(74828, 'esMX', '', 'Escucho un espíritu. ¡Uno poderoso! Mantén a estos goren a raya solo un poco más.', 19865),
(74829, 'esMX', '', 'Gana un poco más de tiempo.', 19865),
(74842, 'esMX', '', 'Tranquilo, chamán. Recupera tu aliento. Ellos pueden abrirse paso por sí solos. Nos reuniremos cuando estés listo.', 19865),
(74843, 'esMX', '', 'Elune-Adore, $c.', 19865),
(74883, 'esMX', '', 'Ishnu-alah, Comandante. Aquí.', 19865),
(74896, 'esMX', '¡¡MUERE, $C!!', '', 19865),
(74897, 'esMX', '¡¡¡No soy tu amigo!!!', '', 19865),
(74898, 'esMX', 'Gracias por salvarnos del Pálido, $n. Me estremece pensar qué horrores podríamos haber encontrado.', 'Gracias por salvarnos del Pálido, $n. Me estremece pensar qué horrores podríamos haber encontrado.', 19865),
(74899, 'esMX', 'De nada.[Vignette Reward Here]', 'De nada.[Vignette Reward Here]', 19865),
(74900, 'esMX', '¿Qué haces aquí?', '¿Qué haces aquí?', 19865),
(74901, 'esMX', '', '', 19865),
(74902, 'esMX', '', '', 19865),
(74903, 'esMX', '', '', 19865),
(74904, 'esMX', 'Has entrado en tu propia tumba, cachorro.', '', 19865),
(74906, 'esMX', 'Se ha ido.', '', 19865),
(74907, 'esMX', '', '', 19865),
(74908, 'esMX', '', '', 19865),
(74909, 'esMX', '', '', 19865),
(74910, 'esMX', '', '', 19865),
(74911, 'esMX', '', '', 19865),
(74931, 'esMX', '', '', 19865),
(74933, 'esMX', 'Hngg... ¿oh? Pude oír a Lokra... hace un momento...', '', 19865),
(74934, 'esMX', 'Pude oír a Lokra... hace un momento...', '', 19865),
(74935, 'esMX', 'Ah, pero ella es la cazadora, no la presa. Y adelante de la manada, como siempre...', '', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(74936, 'esMX', 'Adelante, $gamigo:amiga;. Ya te alcanzaré. Solo necesito un momento para recuperar mi fuerza.', '', 19865),
(74957, 'esMX', '¡¡SQEEEE!!', '', 19865),
(74959, 'esMX', '', 'Shhh... ¡no tan fuerte!', 19865),
(74960, 'esMX', '', 'Gracias. ¡Madre debe estar muy preocupada por mí!', 19865),
(74961, 'esMX', '', 'Puedo regresar al puesto de avanzada desde aquí. ¡Encuéntrame si necesitas algo de peletería!', 19865),
(74983, 'esMX', '¡NOOOO!', '', 19865),
(74999, 'esMX', '¡TE VEO!', '', 19865),
(75000, 'esMX', '', '<Gana se esfuerza en mirar alrededor, luego susurra.>$B$B¿Se... se han ido?', 19865),
(75001, 'esMX', 'Rompe las cadenas.', 'Rompe las cadenas.', 19865),
(75002, 'esMX', '', 'Será más fácil cuidarte si te quedas fuera de la vista, Khadgar.', 19865),
(75003, 'esMX', '', 'Voy hacia la guarida del demonio. Lo capturaremos juntos.', 19865),
(75008, 'esMX', '', 'Aquí.', 19865),
(75009, 'esMX', 'No soy un niño para esconderme tras tu capa, Cordana.', '', 19865),
(75010, 'esMX', '', 'Los seguiremos. ¡Alcáncennos cuando puedan!', 19865),
(75011, 'esMX', '', '¡Rápido, Asha! ¡Tras ellos!', 19865),
(75012, 'esMX', '', '', 19865),
(75013, 'esMX', 'Quédate quieto. Debe llegar más ayuda pronto.', 'Quédate quieto. Debe llegar más ayuda pronto.', 19865),
(75014, 'esMX', 'Nuestro trabajo es vital para el mundo.', '', 19865),
(75015, 'esMX', '', 'Bien hecho. Lo llevaré al puesto de avanzada y veré que esté seguro.', 19865),
(75016, 'esMX', 'Inicia el ritual.', 'Inicia el ritual.', 19865),
(75017, 'esMX', 'La Horda de Hierro sigue atacando desde el sur.', 'La Horda de Hierro sigue atacando desde el sur.', 19865),
(75018, 'esMX', '¿Qué debemos hacer?', '¿Qué debemos hacer?', 19865),
(75019, 'esMX', 'Oye, tú.', 'Oye, tú.', 19865),
