(85760, 'esMX', '¡Están atacando tu scriptorium!', '¡Están atacando tu scriptorium!', 19865),
(85761, 'esMX', '¡Están atacando boutique de gemas!', '¡Están atacando boutique de gemas!', 19865),
(85762, 'esMX', '¡Están atacando tu peletería!', '¡Están atacando tu peletería!', 19865),
(85763, 'esMX', '¿Me vas a mostrar Ashran?', '¿Me vas a mostrar Ashran?', 19865),
(85764, 'esMX', '¡Están atacando tu aserradero!', '¡Están atacando tu aserradero!', 19865),
(85765, 'esMX', '¡Están atacando tu arena de entrenamiento!', '¡Están atacando tu arena de entrenamiento!', 19865),
(85766, 'esMX', '¡No otra vez! Otra cuerda rota.', '¡No otra vez! Otra cuerda rota.', 19865),
(85767, 'esMX', '¡Están atacando tu Torre de los Magos!', '¡Están atacando tu Torre de los Magos!', 19865),
(85768, 'esMX', '¡Están atacando tu Patio de rescate!', '¡Están atacando tu Patio de rescate!', 19865),
(85769, 'esMX', '¡Están atacando tus establos!', '¡Están atacando tus establos!', 19865),
(85770, 'esMX', '¡Están atacando tu almacén!', '¡Están atacando tu almacén!', 19865),
