(89454, 'esMX', 'Volvamos a trabajar.', '', 19865),
(89455, 'esMX', 'Macabro... pero necesario', '', 19865),
(89456, 'esMX', 'Muere bien.', '', 19865),
(89457, 'esMX', 'Ja, demasiado fácil.', '', 19865),
