INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(89535, 'esMX', '¡Disfraz Dagg!', '', 19865),
(89536, 'esMX', 'Tú ser $gel mejor jefe:la mejor jefa; que Dagg haber tenido. Dagg es unánime en eso.', '', 19865),
(89537, 'esMX', 'Tú estar muerto. Dagg es unánime en eso.', '', 19865),
(89538, 'esMX', 'Eso darle a Dagg una idea para un disfraz nuevo.', '', 19865),
(89539, 'esMX', 'Presa fresca.', '', 19865),
(89540, 'esMX', 'Más comida para mi mascota.', '', 19865),
(89541, 'esMX', '¡Ah! Con esto puedo probar mis trampas nuevas.', '', 19865),
(89542, 'esMX', 'Esta... fue una pésima... idea...', '', 19865),
(89543, 'esMX', 'Patético.', '', 19865),
(89544, 'esMX', 'Escogiste el lado equivocado, idiota.', '', 19865),
(89545, 'esMX', '¿Sigues siendo el depredador en la cima de la cadena alimenticia, Comandante?', '', 19865),
(89546, 'esMX', '¡Por el Kirin Tor!', '', 19865),
(89547, 'esMX', '¿Qué crees que lograrás?', '', 19865),
(89548, 'esMX', 'Oh, cielos, ¿crees que vas a ganar?', '', 19865),
(89549, 'esMX', 'Fascinante. Qué bárbaro.', '', 19865),
(89550, 'esMX', 'Estás consciente de que en verdad no estoy aquí, ¿cierto?', '', 19865),
(89551, 'esMX', 'Estoy perdiendo el control de mi imagen...', '', 19865),
(89552, 'esMX', 'Pues, ese fue un resultado interesante.', '', 19865),
(89553, 'esMX', 'Con algo de práctica, podrías haber sido una mayor amenaza.', '', 19865),
(89554, 'esMX', 'Bien hallado, Comandante.', '', 19865),
(89555, 'esMX', 'Saludos, Comandante.', '', 19865),
(89556, 'esMX', '', 'Dibujaré con fuego una sonrisa en tu cara.', 19865),
(89557, 'esMX', '', '¡Jajajajajaja!', 19865),
(89558, 'esMX', '', 'Me pondré tu calavera.', 19865),
(89559, 'esMX', '', 'Haré que te rías.', 19865),
(89560, 'esMX', '', 'Moriré... ¡riendo!', 19865),
(89561, 'esMX', '', 'Quema mi cuerpo... quédate con... mi calavera.', 19865),
(89562, 'esMX', '', 'No te mueras. Aún no acabo contigo.', 19865),
(89563, 'esMX', '', '¡Saluda a tu adiós!', 19865),
(89564, 'esMX', '', 'Cuando mueras, ¿puedo ponerme tu calavera?', 19865),
(89565, 'esMX', '', '¡Que tus enemigos ardan!', 19865),
