(89570, 'esMX', '', '¡Por el honor!', 19865),
(89571, 'esMX', '', 'Idiota sin honor.', 19865),
(89572, 'esMX', '', 'Victoria para los Lobo Gélido.', 19865),
(89573, 'esMX', '', 'Asha... voy en camino...', 19865),
(89574, 'esMX', '', 'Saludo.', 19865),
(89575, 'esMX', 'Esto es lo que llamo un campo lleno de blancos.', '', 19865),
(89576, 'esMX', '¡Voy por ti, $n!', '', 19865),
(89577, 'esMX', 'Estoy... cayendo...', '', 19865),
(89578, 'esMX', '¡La mejor hacha!', '', 19865),
(89579, 'esMX', 'Solicito un vuelo de reconocimiento.', '', 19865),
(89580, 'esMX', 'Puedes ser mi $gcompañero:compañera; cuando quieras.', '', 19865),
(89581, 'esMX', 'Veamos de qué estás $ghecho:hecha;.', '', 19865),
(89582, 'esMX', '¿Te puedes doblar por la mitad? Veamos.', '', 19865),
(89583, 'esMX', '¿Un contendiente?', '', 19865),
(89584, 'esMX', 'Buena... pelea...', '', 19865),
